// Generated by the /ship test coverage audit (Claude).
// Value: protects=route errors reach PostHog unchanged only when PostHog is loaded in the browser, and a telemetry failure never throws out of the boundary;
//   fails_when=a guard or the try/catch is dropped (server, unloaded or failing PostHog throws) or the value is altered before sending;
//   why_new=captureRouteError is new and the router-wide boundary test never reports an error;
//   seam=none; no_claim=real PostHog delivery (posthog-js is mocked at its module boundary).
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
import { captureRouteError } from "@integrations/posthog/capture";

const mocks = vi.hoisted(() => ({
  posthog: { __loaded: true, captureException: vi.fn() },
}));

// posthog-js is installed under apps/web only, so the mock addresses it by path like other web tests.
vi.mock("../../../../../../apps/web/node_modules/posthog-js", () => ({ default: mocks.posthog }));

beforeEach(() => {
  mocks.posthog.__loaded = true;
  mocks.posthog.captureException.mockReset();
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("captureRouteError", () => {
  test("reports a caught Error as-is", () => {
    const error = new Error("Feed failed");

    captureRouteError(error);

    expect(mocks.posthog.captureException).toHaveBeenCalledExactlyOnceWith(error);
  });

  test("passes a thrown non-Error value to PostHog unchanged", () => {
    const thrown = { code: "E_FEED" };

    captureRouteError(thrown);

    expect(mocks.posthog.captureException).toHaveBeenCalledExactlyOnceWith(thrown);
  });

  test("never throws when PostHog itself fails", () => {
    mocks.posthog.captureException.mockImplementationOnce(() => {
      throw new Error("posthog down");
    });

    expect(() => captureRouteError(new Error("Feed failed"))).not.toThrow();
  });

  test("stays silent until PostHog has loaded", () => {
    mocks.posthog.__loaded = false;

    expect(() => captureRouteError(new Error("Feed failed"))).not.toThrow();
    expect(mocks.posthog.captureException).not.toHaveBeenCalled();
  });

  test("does nothing during server rendering", () => {
    vi.stubGlobal("window", undefined);

    expect(() => captureRouteError(new Error("Feed failed"))).not.toThrow();
    expect(mocks.posthog.captureException).not.toHaveBeenCalled();
  });
});
